const RecordRefundOnPurchase = `-- name: RecordRefundOnPurchase :one
WITH refund AS (
    SELECT p.id,
        GREATEST(
            COALESCE(p.refunded_amount, 0),
            COALESCE(
                CASE
                    WHEN $1::text = p.currency THEN $2::integer
                END,
                p.price_at_purchase
            )
        ) AS amount
    FROM purchases p
    WHERE p.tenant_id = $3
        AND p.provider = $4::text
        AND p.provider_payment_id = $5::text
)
UPDATE purchases p
SET refunded_amount = refund.amount,
    refunded_at = CASE
        WHEN refund.amount >= p.price_at_purchase THEN COALESCE(p.refunded_at, NOW())
        ELSE p.refunded_at
    END,
    revoked_at = CASE
        WHEN refund.amount >= p.price_at_purchase THEN COALESCE(p.revoked_at, NOW())
        ELSE p.revoked_at
    END,
    revocation_reason = CASE
        WHEN refund.amount >= p.price_at_purchase THEN COALESCE(p.revocation_reason, 'refund')
        ELSE p.revocation_reason
    END
FROM refund
WHERE p.id = refund.id
RETURNING p.id, p.user_id, p.episode_id, p.price_at_purchase, p.expires_at, p.purchased_at, p.tenant_id, p.provider_checkout_id, p.provider_payment_id, p.refunded_amount, p.refunded_at, p.store, p.store_transaction_id, p.is_test, p.provider, p.currency, p.revoked_at, p.revocation_reason, p.staff_refund_attempt, p.dispute_lost_at, p.kind
`

type RecordRefundOnPurchaseParams struct {
	Currency          sql.NullString `json:"currency"`
	RefundedAmount    sql.NullInt32  `json:"refunded_amount"`
	TenantID          uuid.UUID      `json:"tenant_id"`
	Provider          string         `json:"provider"`
	ProviderPaymentID string         `json:"provider_payment_id"`
}

// Records what the provider has refunded against one purchase, matched by the
// payment the refund notification names. Nothing matches when the payment
// belongs to another tenant, another provider, or no purchase here, and the
// caller reads that empty result as a delivery it has no sale for.
//
// The amount the provider reports is cumulative over every refund against the
// payment, so GREATEST keeps an out-of-order delivery from walking it back, and
// an event that reports no amount at all, or one in a currency other than the
// purchase's, which says nothing comparable to its price, is recorded as a
// refund of the whole price. refunded_at follows from the amount rather than from the event:
// it is set once the refunded total reaches what was paid, and a repeated
// delivery of the same refund leaves the instant already stored. The same
// moment revokes the purchase, unless something revoked it first, whose reason
// it keeps.
func (q *Queries) RecordRefundOnPurchase(ctx context.Context, arg RecordRefundOnPurchaseParams) (Purchase, error) {
	row := q.db.QueryRowContext(ctx, RecordRefundOnPurchase,
		arg.Currency,
		arg.RefundedAmount,
		arg.TenantID,
		arg.Provider,
		arg.ProviderPaymentID,
	)
	var i Purchase
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.EpisodeID,
		&i.PriceAtPurchase,
		&i.ExpiresAt,
		&i.PurchasedAt,
		&i.TenantID,
		&i.ProviderCheckoutID,
		&i.ProviderPaymentID,
		&i.RefundedAmount,
		&i.RefundedAt,
		&i.Store,
		&i.StoreTransactionID,
		&i.IsTest,
		&i.Provider,
		&i.Currency,
		&i.RevokedAt,
		&i.RevocationReason,
		&i.StaffRefundAttempt,
		&i.DisputeLostAt,
		&i.Kind,
	)
	return i, err
}

